 public static int Main(string[] args){if(args.Length!=0)return args[0]=="server"?Server(args):2;string name="sentinel-usb-tab-"+Guid.NewGuid().ToString("N");using(var host=Process.GetCurrentProcess())using(var server=new Process()){server.StartInfo=new ProcessStartInfo(host.MainModule.FileName,"server "+name+" "+host.Id+" "+host.StartTime.ToUniversalTime().Ticks){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};try{server.Start();using(var malformed=new System.IO.Pipes.NamedPipeClientStream(".",name,System.IO.Pipes.PipeDirection.InOut)){malformed.Connect(3000);malformed.WriteByte(0);malformed.Flush();}string response;using(var cancel=new CancellationTokenSource(20000))response=UsbAdmissionTabPipe.Exchange(name,server.Id,server.StartTime.ToUniversalTime().Ticks,"{\"action\":\"status\"}",cancel.Token).GetAwaiter().GetResult();if(response!="{\"state\":\"ok\"}"||!server.WaitForExit(10000)||server.ExitCode!=0)throw new InvalidOperationException("Native tab roundtrip failed");Console.WriteLine("PASS malformed connection refused then authenticated local subprocess pipe roundtrip; no privileged or device action");return 0;}catch(Exception error){Console.WriteLine("FAIL native pipe category "+error.GetType().Name+" hresult "+error.HResult.ToString("X8"));foreach(var f in new StackTrace(error,false).GetFrames()??new StackFrame[0]){var m=f.GetMethod();if(m!=null&&m.DeclaringType!=null&&m.DeclaringType.FullName.Contains("UsbAdmissionTabPipe"))Console.WriteLine("FAIL_FRAME "+m.DeclaringType.Name+"."+m.Name);}try{if(!server.HasExited)server.Kill();server.WaitForExit(1000);if(server.HasExited){string details=server.StandardOutput.ReadToEnd();if(details.Length<2048)Console.WriteLine(details);}}catch{}return 1;}finally{try{if(!server.HasExited)server.Kill();}catch{}}}}
